const cache = new Map();
let converter = null;
let lang = localStorage.getItem('ams_lang') || 'zh-CN';

// Preview adapter: OpenCC is a 1.2MB UMD bundle kept as a static asset, loaded on demand
// for Traditional Chinese instead of blocking the app entry.
function loadOpenCC() {
  if (window.OpenCC) return Promise.resolve(window.OpenCC);
  if (!window.__openccPromise) {
    window.__openccPromise = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = new URL('../../public/vendor/opencc.js', import.meta.url).href;
      script.onload = () => resolve(window.OpenCC);
      script.onerror = () => reject(new Error('opencc unavailable'));
      document.head.appendChild(script);
    }).catch(error => { console.warn('[preview] OpenCC not loaded:', error.message); return null; });
  }
  return window.__openccPromise;
}
function getConverter() {
  if (converter) return converter;
  if (window.OpenCC && typeof window.OpenCC.Converter === 'function') {
    converter = window.OpenCC.Converter({ from: 'cn', to: 'tw' });
  }
  return converter;
}

function toTW(s) {
  const c = getConverter();
  if (!c) return s;
  if (cache.has(s)) return cache.get(s);
  let out = s;
  try { out = c(s); } catch (e) { out = s; }
  cache.set(s, out);
  return out;
}

export function ensureTraditionalConverter() {
  if (converter || lang !== 'zh-TW') return Promise.resolve(converter);
  return loadOpenCC().then(lib => {
    if (lib && typeof lib.Converter === 'function') converter = lib.Converter({ from: 'cn', to: 'tw' });
    return converter;
  });
}

export function t(key, vars) {
  if (key == null) return '';
  let s = pageLabels[key] || String(key);
  if (lang === 'en') s = EN[s] !== undefined ? EN[s] : s;
  else if (lang === 'zh-TW') s = toTW(s);
  if (vars) {
    Object.entries(vars).forEach(([k, v]) => {
      s = s.replaceAll('{' + k + '}', String(v));
    });
  }
  return s;
}

export function setLang(next) {
  lang = next;
  // Translations are memoized; a cached value from the previous language must not leak through.
  cache.clear();
  localStorage.setItem('ams_lang', next);
  document.documentElement.lang = next === 'en' ? 'en' : next === 'zh-TW' ? 'zh-Hant' : 'zh-CN';
}

export function getLang() { return lang; }

export function fmtDT(value) {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value);
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}/${p(d.getMonth() + 1)}/${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

export function fmtDate(value) {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value);
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}/${p(d.getMonth() + 1)}/${p(d.getDate())}`;
}

export function fmtTime(value) {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
}

export function relTime(value) {
  if (!value) return '';
  const diff = Math.max(0, Date.now() - new Date(value).getTime());
  const min = Math.floor(diff / 60000);
  if (min < 1) return lang === 'en' ? 'just now' : '刚刚';
  if (min < 60) return `${min}${lang === 'en' ? ' min ago' : ' 分钟前'}`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}${lang === 'en' ? ' hr ago' : ' 小时前'}`;
  const day = Math.floor(hr / 24);
  return `${day}${lang === 'en' ? ' d ago' : ' 天前'}`;
}
